/*
 * A246356  Numbers k such that d(r,k) = 0 and d(s,k) = 0, where d(x,k) = k-th
 *          binary digit of x, r = {sqrt(2)}, s = {sqrt(3)}, and { } =
 *          fractional part.
 * https://oeis.org/A246356
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, base
 * Formula:   a(n) = the n-th integer k such that the k‑th binary digit of the
 *            fractional part of sqrt(2) and that of sqrt(3) are both 0. The
 *            sequence is generated by computing the binary digits of sqrt(2)
 *            and sqrt(3) by a digit–by–digit integer square–root algorithm
 *            that avoids floating point arithmetic
 * Range:     u8 n <= 63, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* ---- Big integer for non‑negative values (little‑endian, up to ~ 20000 bits) ---- */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#define MAX_LIMBS 2000   /* > 20000 bits / 32 */

typedef struct {
    size_t len;                /* number of limbs used */
    uint32_t v[MAX_LIMBS];     /* limbs, little‑endian */
} BigInt;

static void bi_zero(BigInt *a) {
    a->len = 1;
    a->v[0] = 0;
}

static void bi_copy(BigInt *dst, const BigInt *src) {
    dst->len = src->len;
    memcpy(dst->v, src->v, src->len * sizeof(uint32_t));
}

static void bi_shift_left(BigInt *a, unsigned bits) {
    /* bits ∈ {1,2}.  Assumes capacity is sufficient. */
    if (bits == 0) return;
    uint64_t carry = 0;
    for (size_t i = 0; i < a->len; ++i) {
        uint64_t tmp = ((uint64_t)a->v[i] << bits) | carry;
        a->v[i] = (uint32_t)(tmp & 0xffffffffu);
        carry = tmp >> 32;
    }
    if (carry != 0) {
        assert(a->len < MAX_LIMBS);
        a->v[a->len++] = (uint32_t)carry;
    }
}

static void bi_add_small(BigInt *a, uint32_t add) {
    uint64_t sum = (uint64_t)a->v[0] + add;
    a->v[0] = (uint32_t)(sum & 0xffffffffu);
    uint64_t carry = sum >> 32;
    size_t i = 1;
    while (carry && i < a->len) {
        uint64_t s = (uint64_t)a->v[i] + carry;
        a->v[i] = (uint32_t)(s & 0xffffffffu);
        carry = s >> 32;
        ++i;
    }
    if (carry) {
        assert(a->len < MAX_LIMBS);
        a->v[a->len++] = (uint32_t)carry;
    }
}

static int bi_cmp(const BigInt *a, const BigInt *b) {
    if (a->len != b->len) return (a->len > b->len) ? 1 : -1;
    for (size_t i = a->len; i-- > 0; ) {
        if (a->v[i] != b->v[i]) return (a->v[i] > b->v[i]) ? 1 : -1;
    }
    return 0;
}

static void bi_sub_assign(BigInt *a, const BigInt *b) {
    /* assumes a >= b */
    uint64_t borrow = 0;
    for (size_t i = 0; i < a->len; ++i) {
        uint64_t bi = b->len > i ? b->v[i] : 0;
        uint64_t sub = (uint64_t)a->v[i] - bi - borrow;
        a->v[i] = (uint32_t)(sub & 0xffffffffu);
        borrow = (sub >> 63) & 1;  /* borrow bit */
    }
    /* trim leading zeros */
    while (a->len > 1 && a->v[a->len - 1] == 0) --a->len;
}

/* ---- Generator for the binary digits of sqrt(const) ---- */
typedef struct {
    BigInt root;      /* current partial root    */
    BigInt rem;       /* current remainder       */
    uint8_t *bits;    /* array of 0/1 bits (bits[0] = 1, integer part) */
    size_t bits_count;     /* number of bits stored so far          */
    size_t bits_cap;       /* allocated capacity                     */
    uint32_t first_pair;   /* 2 for sqrt(2), 3 for sqrt(3)          */
} SqrtGen;

static void sqrt_gen_init(SqrtGen *g, uint32_t first_pair) {
    bi_zero(&g->root);
    bi_zero(&g->rem);
    g->bits = NULL;
    g->bits_count = 0;
    g->bits_cap = 0;
    g->first_pair = first_pair;
}

static void sqrt_gen_grow_bits(SqrtGen *g, size_t new_cap) {
    if (new_cap > g->bits_cap) {
        g->bits_cap = new_cap;
        g->bits = (uint8_t *)realloc(g->bits, g->bits_cap * sizeof(uint8_t));
    }
}

static void sqrt_gen_generate(SqrtGen *g, size_t target_bits) {
    /* generate bits until g->bits_count == target_bits */
    BigInt cand;
    while (g->bits_count < target_bits) {
        size_t i = g->bits_count;                       /* next bit index */
        uint32_t next_pair = (i == 0) ? g->first_pair : 0u;

        /* r = r << 2; r += next_pair; */
        bi_shift_left(&g->rem, 2);
        bi_add_small(&g->rem, next_pair);

        /* cand = (root << 2) + 1; */
        bi_copy(&cand, &g->root);
        bi_shift_left(&cand, 2);
        bi_add_small(&cand, 1);

        /* if r >= cand: r -= cand; root = (root << 1) | 1; else root <<= 1; */
        uint8_t bit = 0;
        if (bi_cmp(&g->rem, &cand) >= 0) {
            bi_sub_assign(&g->rem, &cand);
            bi_shift_left(&g->root, 1);
            bi_add_small(&g->root, 1);
            bit = 1;
        } else {
            bi_shift_left(&g->root, 1);
        }

        /* store bit */
        sqrt_gen_grow_bits(g, g->bits_count + 1);
        g->bits[g->bits_count] = bit;
        ++g->bits_count;
    }
}

/* ---- Sequence handling ---- */
static seq_t *seq = NULL;
static size_t seq_len = 0;
static size_t seq_cap = 0;

static void seq_grow(size_t new_cap) {
    if (new_cap > seq_cap) {
        size_t cap = seq_cap ? seq_cap * 2 : 16;
        if (cap < new_cap) cap = new_cap;
        seq = (seq_t *)realloc(seq, cap * sizeof(seq_t));
        seq_cap = cap;
    }
}

/* ---- Main function ---- */
static SqrtGen gen2;
static SqrtGen gen3;
static idx_t last_k_checked = 0;   /* highest k that has been examined */

seq_t a(idx_t n) {   /* n >= 1 */
    static int initialized = 0;
    if (!initialized) {
        sqrt_gen_init(&gen2, 2u);
        sqrt_gen_init(&gen3, 3u);
        seq = NULL;
        seq_len = seq_cap = 0;
        last_k_checked = 0;
        initialized = 1;
    }

    /* ensure enough terms in the sequence */
    while (seq_len < n) {
        ++last_k_checked;   /* examine next k */

        /* make sure bits for both generators exist */
        size_t need_bits = last_k_checked + 1;   /* includes integer bit */
        sqrt_gen_generate(&gen2, need_bits);
        sqrt_gen_generate(&gen3, need_bits);

        /* next term if both digits are 0 */
        if (gen2.bits[last_k_checked] == 0 && gen3.bits[last_k_checked] == 0) {
            seq_grow(seq_len + 1);
            seq[seq_len++] = (seq_t)last_k_checked;
        }
    }

    return seq[n - 1];
}
